/* ─── Buttons: solid (one per view), line (the rest), danger, ghost ─── */
.btn { height: var(--control-md); display: inline-flex; align-items: center; justify-content: center; gap: var(--s3); padding: 0 24px; font-size: var(--text-sm); font-weight: 500; white-space: nowrap; border-radius: var(--radius); transition: transform var(--base), background var(--fast), color var(--fast); }
.btn:active:not(:disabled) { transform: scale(0.98); }
.btn:disabled { opacity: 0.55; cursor: not-allowed; }
.btn-solid { background: var(--foreground); color: var(--background); }
.btn-solid:hover:not(:disabled) { background: var(--ink-2); }
.btn-line { box-shadow: inset 0 0 0 1px var(--foreground); }
.btn-line:hover:not(:disabled) { background: var(--foreground); color: var(--background); }
.btn-danger { box-shadow: inset 0 0 0 1px var(--danger); color: var(--danger); }
.btn-danger:hover:not(:disabled) { background: var(--danger); color: var(--background); }
.btn-ghost { min-height: 0; padding-inline-start: 0; padding-inline-end: 0; text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--muted); }
.btn-ghost:hover:not(:disabled) { text-decoration-color: currentColor; }
.btn-sm { height: var(--control-sm); padding: 0 12px; font-size: var(--text-xs); }
.btn-lg { height: var(--control-lg); padding: 0 32px; font-size: var(--text-base); }
.btn-ghost.btn-sm, .btn-ghost.btn-lg { height: auto; padding-block: var(--s2); }
.btn-block { width: 100%; }

/* ─── Dropdown menu: <details class="dropdown">; monoline.js closes it on Escape and outside click ─── */
.dropdown { position: relative; display: inline-block; }
.dropdown > summary { list-style: none; cursor: pointer; }
.dropdown > summary::-webkit-details-marker { display: none; }
.menu { position: absolute; inset-inline-start: 0; top: calc(100% + var(--s2)); z-index: var(--z-drawer); min-width: 200px; background: var(--background); border: 1px solid var(--foreground); padding: var(--s1) 0; }
.menu-end { inset-inline-start: auto; inset-inline-end: 0; }
.menu-item { overflow-wrap: anywhere; display: flex; justify-content: space-between; gap: var(--s5); width: 100%; padding: var(--s2) var(--s4); font-size: var(--text-sm); text-align: start; }
.menu-item:hover, .menu-item:focus-visible { background: var(--foreground); color: var(--background); outline-offset: -2px; }
.menu-item.danger:hover { background: var(--danger); color: var(--background); }
.menu-sep { border: 0; border-top: 1px solid var(--rule); margin: var(--s1) 0; }

/* Overflow list: one clipped row. Items that do not fit stay in flow for measuring but are hidden and out of the tab order. */
.overflow-list { display: flex; align-items: center; gap: var(--s2); min-width: 0; overflow: hidden; position: relative; }
.overflow-list-items { display: flex; flex-wrap: nowrap; gap: var(--s2); margin: 0; padding: 0; list-style: none; min-width: 0; }
.overflow-list-item { flex: none; white-space: nowrap; }
.overflow-list-item[data-hidden] { visibility: hidden; position: absolute; pointer-events: none; }
.overflow-list-more { flex: none; }

usage:
import {OverflowList, Tag} from '@monoline/react';

const names = ['Design', 'Engineering', 'Marketing', 'Support', 'Finance', 'Legal', 'People', 'Research'];

<div style={{maxWidth: '320px', resize: 'horizontal', overflow: 'auto', paddingBlock: 'var(--s2)'}}>
  <OverflowList items={names.map((n) => ({id: n, label: <Tag>{n}</Tag>}))} />
</div>

